package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
public class LoginServlet extends HttpServlet {
  protected void doPost(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {
    request.setCharacterEncoding("UTF-8");
    String user = request.getParameter("username");
    String pwd = request.getParameter("password");
    if ("admin".equals(user) && "123456".equals(pwd)) {
      request.getSession().setAttribute("user", user);
      response.sendRedirect("welcome.jsp");
    } else {
      request.setAttribute("msg", "用户名或密码错误");
      request.getRequestDispatcher("/login.jsp").forward(request, response);
    }
  }
}
<!-- web.xml -->
<servlet><servlet-name>login</servlet-name>
  <servlet-class>com.demo.LoginServlet</servlet-class></servlet>
<servlet-mapping><servlet-name>login</servlet-name>
  <url-pattern>/login</url-pattern></servlet-mapping>

package com.demo;
import java.io.*;
import javax.servlet.*;
public class EncodingFilter implements Filter {
  private String encoding;
  public void init(FilterConfig config) throws ServletException {
    encoding = config.getInitParameter("encoding");
    if (encoding == null) encoding = "UTF-8";
  }
  public void doFilter(ServletRequest req, ServletResponse resp, FilterChain chain)
      throws IOException, ServletException {
    req.setCharacterEncoding(encoding);
    chain.doFilter(req, resp);
  }
  public void destroy() { }
}
<!-- web.xml -->
<filter>
  <filter-name>enc</filter-name>
  <filter-class>com.demo.EncodingFilter</filter-class>
  <init-param><param-name>encoding</param-name><param-value>UTF-8</param-value></init-param>
</filter>
<filter-mapping><filter-name>enc</filter-name><url-pattern>/*</url-pattern></filter-mapping>

package com.demo;
import javax.servlet.ServletContext;
import javax.servlet.annotation.WebListener;
import javax.servlet.http.*;
@WebListener
public class OnlineListener implements HttpSessionListener {
  public void sessionCreated(HttpSessionEvent se) {
    change(se.getSession().getServletContext(), 1);
  }
  public void sessionDestroyed(HttpSessionEvent se) {
    change(se.getSession().getServletContext(), -1);
  }
  private synchronized void change(ServletContext ctx, int d) {
    Integer n = (Integer) ctx.getAttribute("online");
    if (n == null) n = 0;
    ctx.setAttribute("online", n + d);
  }
}
<%-- 在JSP中显示在线人数 --%>
